style.css:
@-moz-document domain("google.com") {
body {
        background: url("https://japanesenostalgiccar.com/wordpress/wp-content/uploads/2013/07/Initial-D.jpg") no-repeat center center fixed !important;
        background-size: cover !important; /* Adatta l'immagine allo schermo */
    }

    #logo {
        display: block !important; /* Mostra il logo di Google */
    }

    .lnXdpd {
        opacity: 1 !important; /* Mantiene il logo visibile */
    }

    input {
        background-color: rgba(255, 255, 255, 0.8) !important; /* Migliora la leggibilità del campo di ricerca */
        border: 1px solid rgba(0, 0, 0, 0.1) !important; /* Bordo leggero per chiarezza */
    }

    .FPdoLc, .fbar {
        background-color: rgba(255, 255, 255, 0.5) !important; /* Sfondo trasparente per i pulsanti */
        border-radius: 10px;
    }
}
